x_938076_backup_0_backup_scripts.script:
var validArr = [{
    "TradeID": "000000131ba652d091f24156b04bcbe0",
    "reasonCode": "CONF",
    "reasonDesc": "FX Calculated by Approval"
}, {
    "TradeID": "000011ef97ee5ad0f88a7fa71153af96",
    "reasonCode": "MATCH",
    "reasonDesc": "Cancellation from GHSS"
}];

var caseArr = [];
var obj;
var caseSysId;
for (var j = 0; j < validArr.length; j++) {
    var tradeSysId = validArr[j]['TradeID'];
    // Create the custody case
    var grcustodycase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
    grcustodycase.initialize();
    grcustodycase.state = 1;
    grcustodycase.short_description = 'Manually triggered by Bulk processing';
    grcustodycase.description = 'Manually triggered by Bulk processing';
    grcustodycase.trade_id = tradeSysId;
    grcustodycase.bulk_id = '2728304a1b926e90cf016467b04bcb86'; // Use the bulk record ID passed to the function
    grcustodycase.triggered_by = '19c79fbb1ba30a10c6ada6c7b04bcbd5'; // Static sys_id as per your logic
    grcustodycase.case_status = 'ec34a3731b270a10c6ada6c7b04bcb7a';
    grcustodycase.reinitiate_process = false;
    caseSysId = grcustodycase.insert();
    obj = {
        TradeRef: tradeSysId,
        caseSysId: caseSysId
    };

    caseArr.push(JSON.stringify(obj) + '');
}


var validMap = {};
validArr.forEach(function(item) {
    validMap[item.TradeID] = {
        reasonCode: item.reasonCode,
        reasonDesc: item.reasonDesc
    };
});
caseArr.forEach(function(caseItem) {
    var tradeRef = caseItem.TradeRef;
    if (validMap.hasOwnProperty(tradeRef)) { //comparison of newly created map and the case array newly created
        finalObject[tradeRef] = { // Use TradeRef (which matches TradeID) as the key
            "TradeRef": tradeRef, // Include TradeRef in the value object
            "caseID": caseItem.caseSysId, // Include TradeRef in the value object
            "reasonCode": validMap[tradeRef].reasonCode, //from validarray
            "reasonDesc": validMap[tradeRef].reasonDesc
        };
        finalArr.push(JSON.stringify(finalObject[tradeRef]) + ' ');
    }
});
gs.info('Case Array:' + caseArr.toString());
gs.info('Valid Map:' + JSON.stringify(validMap));

//Case Array:{"TradeRef":"000000131ba652d091f24156b04bcbe0","caseSysId":"4360584b1bea66102ac120a8b04bcb6f"},{"TradeRef":"000011ef97ee5ad0f88a7fa71153af96","caseSysId":"8760d84b1bea66102ac120a8b04bcb03"}
// Valid Array:{"000000131ba652d091f24156b04bcbe0":{"reasonCode":"CONF","reasonDesc":"FX Calculated by Approval"},"000011ef97ee5ad0f88a7fa71153af96":{"reasonCode":"MATCH","reasonDesc":"Cancellation from GHSS"}}

var count = caseArr.length; //2
gs.info('CASe len ' + count);
var taskArray = [];


while (caseArr.length > 0) { //based on the length
    for (var i = 0; i < caseArr.length; i++) {
        (function executeRow(index) {
            var getData = JSON.parse(caseArr[index]); // Parse the current case data
            var trdRef = getData.TradeRef;
            var caseRef = getData.caseSysId;
            var gr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            gr.addQuery('trade_case_id', caseRef);
            gr.addQuery('trade_id', trdRef);
            gr.addQuery('trade_task_type', 'Maker');
            gr.query();
            if (gr.next()) {
                gs.info('Updating Task: ' + gr.number);
                // Perform the update
                gr.short_description = 'Updated by script';
                //gr.update();
                // Remove the processed case from the array
				//arr = ['MSS1', 'MSS2'];
				//arr = ['MSS1']
                caseArr.splice(index, 1);  //this will remove the i value which will reduce since condition met and the i value will be reduced by 1

                gs.info('Remaining cases: ' + caseArr.length);
            } else {
                gs.info('No task found for TradeRef: ' + trdRef + ' and CaseSysId: ' + caseRef);
            }
        })(i);
    }
}
